<?php require 'config.php';if(isset($_GET['remove'])){unset($_SESSION['cart'][(int)$_GET['remove']]);flash('Item removed.');go('/MediHome/cart.php');}if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';$id=(int)($_POST['medicine_id']??0);if($action==='add'&&$id){$s=$pdo->prepare('SELECT stock FROM medicines WHERE id=?');$s->execute([$id]);$p=$s->fetch();if($p&&(int)$p['stock']>0){$qty=max(1,min((int)$p['stock'],(int)($_POST['quantity']??1)));$_SESSION['cart'][$id]=min((int)$p['stock'],(int)($_SESSION['cart'][$id]??0)+$qty);flash('Added to cart.');}else flash('Out of stock.','error');}elseif($action==='update'){foreach($_POST['qty']??[] as $pid=>$qty){$pid=(int)$pid;$qty=(int)$qty;if($qty<1)unset($_SESSION['cart'][$pid]);else{$s=$pdo->prepare('SELECT stock FROM medicines WHERE id=?');$s->execute([$pid]);$r=$s->fetch();if($r)$_SESSION['cart'][$pid]=min((int)$r['stock'],$qty);}}flash('Cart updated.');}elseif($action==='remove'){unset($_SESSION['cart'][$id]);flash('Item removed.');}go('/MediHome/cart.php');}
$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT m.*,c.name category_name FROM medicines m JOIN categories c ON c.id=m.category_id WHERE m.id IN ($in)");$s->execute($ids);foreach($s->fetchAll() as $p){$p['qty']=min((int)$cart[$p['id']],(int)$p['stock']);$p['line']=$p['qty']*(float)$p['price'];$total+=$p['line'];$items[]=$p;}}$title='Your Cart | MediHome';require 'includes/header.php';?>
<div class="pagehead"><span class="eyebrow">Your selection</span><h1>Your shopping cart</h1><p>Check quantities, review your items and continue when ready.</p></div><?php if(!$items):?><div class="empty"><div style="font-size:3rem">🛒</div><h2>Your cart is empty</h2><p>Browse our categories to find what you need.</p><a class="btn" href="/MediHome/medicines.php">Browse products</a></div><?php else:?><form method="post"><input type="hidden" name="action" value="update"><div class="cart-list"><?php foreach($items as $p):?><article class="cart-item"><a class="cart-thumb" href="/MediHome/product.php?id=<?=(int)$p['id']?>"><?php if(!empty($p['image_url'])):?><img src="<?=e($p['image_url'])?>" alt="<?=e($p['name'])?>"><?php else:?>💊<?php endif;?></a><div class="cart-info"><small><?=e($p['category_name'])?></small><h2><a href="/MediHome/product.php?id=<?=(int)$p['id']?>"><?=e($p['name'])?></a></h2><p><?=e($p['description'])?></p><div class="cart-price">Unit price: <strong><?=money($p['price'])?></strong></div><label class="qty-label">Quantity <input class="input" type="number" min="0" max="<?=(int)$p['stock']?>" name="qty[<?=(int)$p['id']?>]" value="<?=(int)$p['qty']?>"></label><div class="cart-line-total">Item total: <strong><?=money($p['line'])?></strong></div><div class="cart-actions"><button class="btn ghost" type="submit">Update quantity</button><a class="btn ghost" href="/MediHome/cart.php?remove=<?=(int)$p['id']?>">Remove item</a><a class="btn" href="/MediHome/checkout.php">Proceed to checkout</a></div></div></article><?php endforeach;?></div><aside class="cart-summary"><div><span>Items</span><strong><?=array_sum(array_column($items,'qty'))?></strong></div><div><span>Subtotal</span><strong class="subtotal"><?=money($total)?></strong></div><p>Delivery charges, if applicable, will be shown before order confirmation.</p><a class="btn" href="/MediHome/checkout.php">Continue to checkout →</a><a class="btn ghost" href="/MediHome/medicines.php">Continue shopping</a></aside></form><?php endif;?><?php require 'includes/footer.php';?>